def dehydrate_time(value):
    """
    Dehydrator for `time` values.

    :param value:
    :type value: datetime.time
    :return: ISO formatted string representation of the time, or None if value is None.
    """
    if value is None:
        return None
    # Ensure the value is a datetime.time instance
    try:
        # The datetime.time object has an isoformat method that returns a JSON‑serialisable string.
        return value.isoformat()
    except AttributeError:
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}") from None
    except Exception as exc:
        # Catch any unexpected errors and raise a TypeError for consistency
        raise TypeError(f"Error dehydrating time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict representation of the point or None if value is None
    """
    # Return None for a None input
    if value is None:
        return None

    # Helper to extract coordinates from a tuple or list
    def _from_sequence(seq):
        if len(seq) == 2:
            return {"x": seq[0], "y": seq[1]}
        elif len(seq) == 3:
            return {"x": seq[0], "y": seq[1], "z": seq[2]}
        else:
            raise TypeError("Sequence must be of length 2 or 3 to represent a point")

    # If the value is a tuple or list, treat it as coordinates
    if isinstance(value, (tuple, list)):
        try:
            return _from_sequence(value)
        except Exception as exc:
            raise TypeError(f"Cannot dehydrate sequence {value!r}: {exc}") from exc

    # If the value is a dict with x and y (and optionally z), return it as is
    if isinstance(value, dict):
        if "x" in value and "y" in value:
            # Ensure no unexpected keys
            allowed_keys = {"x", "y", "z"}
            if not set(value.keys()).issubset(allowed_keys):
                raise TypeError(f"Dictionary contains unexpected keys: {set(value.keys()) - allowed_keys}")
            return {k: value[k] for k in ("x", "y", "z") if k in value}
        else:
            raise TypeError("Dictionary must contain at least 'x' and 'y' keys")

    # For objects with attributes x and y (and optionally z)
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
    except AttributeError as exc:
        raise TypeError(f"Object {value!r} does not have required 'x' and 'y' attributes") from exc

    result = {"x": x, "y": y}
    # Include z if present
    if hasattr(value, "z"):
        result["z"] = getattr(value, "z")
    return result

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # If the record stores its data in a dict-like attribute named 'data'
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())

        # If the instance itself behaves like a dict
        if isinstance(self, dict):
            return list(self.keys())

        # Fallback: use the instance's __dict__ if available
        if hasattr(self, "__dict__"):
            return list(self.__dict__.keys())

        # If none of the above, raise an informative error
        raise AttributeError("No dict-like structure found in the record")
    except Exception as exc:
        raise RuntimeError("Failed to retrieve keys from the record") from exc

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Ensure the container has a data attribute
    if not hasattr(self, "_data"):
        raise AttributeError("The object does not contain a '_data' attribute.")
    data = self._data

    # If the data is a dictionary, use its keys for indexing
    if isinstance(data, dict):
        data = list(data.keys())

    # Attempt to find the index
    try:
        return data.index(key)
    except AttributeError:
        # data is not a sequence
        raise TypeError(f"Unsupported data type {type(data).__name__} for indexing.")
    except ValueError:
        # key not found
        raise ValueError(f"Key {key!r} not found in the container.")
    except Exception as exc:
        # Re-raise any other unexpected exceptions with context
        raise RuntimeError(f"An unexpected error occurred while searching for {key!r}: {exc}") from exc

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine if the record behaves like a mapping
    is_mapping = hasattr(self, "keys") and callable(getattr(self, "keys", None))

    # If no keys are provided, return all values
    if not keys:
        if is_mapping:
            return list(self.values())
        else:
            return list(self)

    # Prepare a list of values for index-based access
    if is_mapping:
        values_list = list(self.values())
    else:
        values_list = list(self)

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            try:
                result.append(values_list[key])
            except IndexError as exc:
                raise IndexError(f"Index {key} out of range") from exc
        else:
            # Key-based access
            if is_mapping:
                try:
                    result.append(self[key])
                except KeyError as exc:
                    raise KeyError(f"Key {key!r} not found") from exc
            else:
                raise TypeError(f"Cannot use key {key!r} on non-mapping record")
    return result

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise TypeError("timer must be callable")

    from functools import wraps
    from collections import OrderedDict, namedtuple

    CacheInfo = namedtuple('CacheInfo', ['hits', 'misses', 'maxsize', 'currsize'])

    def _make_key(args, kwds, typed):
        key = args
        if typed:
            key += tuple(type(v) for v in args)
        if kwds:
            items = tuple(sorted(kwds.items()))
            if typed:
                items = tuple((k, v, type(v)) for k, v in items)
            key += items
        return key

    def decorator(func):
        cache = OrderedDict()
        hits = misses = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs, typed)
            now = timer()
            if key in cache:
                value, ts = cache[key]
                if now - ts < ttl:
                    hits += 1
                    cache.move_to_end(key)
                    return value
                else:
                    # expired entry
                    del cache[key]
            misses += 1
            result = func(*args, **kwargs)
            cache[key] = (result, now)
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        def cache_clear():
            nonlocal cache, hits, misses
            cache.clear()
            hits = misses = 0

        def cache_info():
            return CacheInfo(hits, misses, maxsize, len(cache))

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is None or maxsize <= 0:
        # No caching
        def decorator(func):
            return func
        return decorator

    def decorator(func):
        cache = {}
        order = []  # list of keys, most recent at front

        def make_key(args, kwargs):
            try:
                if typed:
                    key_pos = tuple((arg, type(arg)) for arg in args)
                    key_kw = tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
                else:
                    key_pos = args
                    key_kw = tuple(sorted(kwargs.items()))
                return key_pos + key_kw
            except TypeError:
                # Unhashable arguments; return None to indicate no caching
                return None

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key is None:
                # Cannot cache; just call the function
                return func(*args, **kwargs)
            if key in cache:
                # Move key to front (most recent)
                order.remove(key)
                order.insert(0, key)
                return cache[key]
            # Compute result
            result = func(*args, **kwargs)
            # Add to cache
            cache[key] = result
            order.insert(0, key)
            # Evict if over size
            if len(order) > maxsize:
                # Evict most recent (front) to follow MRU policy
                evict_key = order.pop(0)
                cache.pop(evict_key, None)
            return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    # Validate parameters
    try:
        maxsize = int(maxsize)
    except Exception:
        maxsize = 0
    if maxsize <= 0:
        # No caching
        def decorator(func):
            return func
        return decorator
    if not isinstance(typed, bool):
        typed = False

    def decorator(func):
        import functools
        cache = {}
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            try:
                if typed:
                    key = (tuple((arg, type(arg)) for arg in args),
                           tuple((k, type(v)) for k, v in sorted(kwargs.items())))
                else:
                    key = (args, tuple(sorted(kwargs.items())))
            except TypeError:
                # Unhashable arguments; skip caching
                return func(*args, **kwargs)

            if key in cache:
                result, count = cache[key]
                cache[key] = (result, count + 1)
                return result
            # Compute result
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Do not cache exceptions
                raise
            # Evict if necessary
            if len(cache) >= maxsize:
                # Find key with minimum count
                min_key = None
                min_count = None
                for k, (_, c) in cache.items():
                    if min_count is None or c < min_count:
                        min_count = c
                        min_key = k
                if min_key is not None:
                    del cache[min_key]
            cache[key] = (result, 1)
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Determine the underlying mapping that stores the items
    mapping = None
    for attr in ("data", "mapping", "store", "dict"):
        if hasattr(self, attr):
            candidate = getattr(self, attr)
            if isinstance(candidate, dict) or (hasattr(candidate, "pop") and hasattr(candidate, "__iter__")):
                mapping = candidate
                break
    if mapping is None:
        # Fallback: the instance itself might be a dict-like object
        if isinstance(self, dict) or (hasattr(self, "pop") and hasattr(self, "__iter__")):
            mapping = self
        else:
            raise AttributeError("No underlying mapping found for popitem operation.")
    # Attempt to pop the first inserted item
    try:
        first_key = next(iter(mapping))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")
    value = mapping.pop(first_key)
    return first_key, value

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except Exception as exc:
        # Re-raise with a clearer message if the key is unhashable
        if isinstance(exc, TypeError) and "unhashable type" in str(exc):
            raise TypeError(f"unhashable type: {type(key).__name__}") from exc
        raise

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError as e:
        # Provide a clearer error message for unhashable keys
        raise TypeError(f"unhashable type: '{type(key).__name__}'") from e
    except Exception as e:
        # Re-raise any other unexpected exceptions
        raise e

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Generate cache key
            try:
                k = key(*args, **kwargs)
            except Exception as e:
                raise RuntimeError(f"Key function raised an exception: {e}") from e

            # Helper to get from cache
            def get_from_cache():
                if hasattr(cache, "__contains__") and k in cache:
                    return cache[k]
                if hasattr(cache, "get"):
                    val = cache.get(k)
                    if val is not None:
                        return val
                raise KeyError

            # Helper to set cache
            def set_in_cache(value):
                if hasattr(cache, "__setitem__"):
                    cache[k] = value
                elif hasattr(cache, "set"):
                    cache.set(k, value)
                else:
                    raise AttributeError("Cache object does not support setting items")

            # Access cache with optional lock
            if lock is not None:
                try:
                    with lock:
                        try:
                            return get_from_cache()
                        except KeyError:
                            result = func(*args, **kwargs)
                            set_in_cache(result)
                            return result
                except Exception as e:
                    raise RuntimeError(f"Cache access with lock failed: {e}") from e
            else:
                try:
                    return get_from_cache()
                except KeyError:
                    result = func(*args, **kwargs)
                    set_in_cache(result)
                    return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        name = self.__class__.__name__
    except Exception:
        return None
    if not isinstance(name, str):
        return name
    suffixes = ('Py', 'Fallback')
    while True:
        for suffix in suffixes:
            if name.endswith(suffix):
                name = name[:-len(suffix)]
                break
        else:
            break
    return name

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
    except Exception as exc:
        raise ImportError("zope.interface is required for directlyProvidedBy") from exc
    try:
        return _directlyProvidedBy(object)
    except TypeError as exc:
        raise ValueError(f"Object {object!r} does not support interface declaration") from exc
    except Exception as exc:
        raise ValueError(f"Failed to retrieve directly provided interfaces for {object!r}") from exc

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("all must be a boolean")
    cls = type(self)
    names_set = set()
    if all:
        for base in cls.__mro__:
            if base is object:
                continue
            for key, val in base.__dict__.items():
                if key.startswith('_'):
                    continue
                if callable(val):
                    continue
                names_set.add(key)
    else:
        for key, val in cls.__dict__.items():
            if key.startswith('_'):
                continue
            if callable(val):
                continue
            names_set.add(key)
    return sorted(names_set)

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError("output must be a list or None")

    # Helper to determine if an object is a leaf (interface or implements spec)
    def _is_leaf(obj):
        # Individual interface: a type (class)
        if isinstance(obj, type):
            return True
        # Implements spec: a tuple of (interface, spec)
        if isinstance(obj, tuple) and len(obj) == 2 and isinstance(obj[0], type):
            return True
        # String or bytes are considered leaf (specs)
        if isinstance(obj, (str, bytes)):
            return True
        return False

    # If sequence is None, nothing to do
    if sequence is None:
        return output

    # If sequence is a leaf, append and return
    if _is_leaf(sequence):
        output.append(sequence)
        return output

    # If sequence is not iterable (e.g., a single object), treat as leaf
    try:
        iter(sequence)
    except TypeError:
        output.append(sequence)
        return output

    # If sequence is a string or bytes, treat as leaf
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # Iterate over the sequence and recursively normalize
    for item in sequence:
        if _is_leaf(item):
            output.append(item)
        else:
            # Recursively handle nested iterables
            _normalizeargs(item, output)

    return output

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        return not _c_optimizations_required()
    except NameError as exc:
        raise NameError("`_c_optimizations_required` is not defined.") from exc
    except Exception as exc:
        raise RuntimeError("Failed to determine if C optimizations are required.") from exc

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is truthy, C optimizations are not required.
        # If it is falsy or not defined, C optimizations are required.
        return not bool(globals().get("PURE_PYTHON", False))
    except Exception:
        # In case of any unexpected error, default to not requiring C optimizations.
        return False

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    initial = getattr(self, "initial_value", None)
    if initial is not None:
        # If bins already exist and are a list, reuse its length
        if hasattr(self, "bins") and isinstance(self.bins, list):
            self.bins = [initial] * len(self.bins)
        else:
            # No existing bins; create a single bin with the initial value
            self.bins = [initial]
    else:
        # No initial_value; try to use make_bins if available
        make_bins = getattr(self, "make_bins", None)
        if callable(make_bins):
            try:
                bins = make_bins()
            except Exception as exc:
                raise RuntimeError(f"make_bins() raised an exception: {exc}") from exc
            if not isinstance(bins, list):
                raise TypeError("make_bins() must return a list of bins")
            self.bins = bins
        else:
            # Fallback: empty bins
            self.bins = []

    # Optional: reset any other state if present
    if hasattr(self, "total"):
        try:
            self.total = 0
        except Exception:
            pass
    if hasattr(self, "count"):
        try:
            self.count = 0
        except Exception:
            pass
    if hasattr(self, "min"):
        try:
            self.min = None
        except Exception:
            pass
    if hasattr(self, "max"):
        try:
            self.max = None
        except Exception:
            pass
    if hasattr(self, "mean"):
        try:
            self.mean = None
        except Exception:
            pass
    if hasattr(self, "std"):
        try:
            self.std = None
        except Exception:
            pass
    if hasattr(self, "median"):
        try:
            self.median = None
        except Exception:
            pass
    if hasattr(self, "mode"):
        try:
            self.mode = None
        except Exception:
            pass
    if hasattr(self, "skew"):
        try:
            self.skew = None
        except Exception:
            pass
    if hasattr(self, "kurtosis"):
        try:
            self.kurtosis = None
        except Exception:
            pass
    if hasattr(self, "hist"):
        try:
            self.hist = None
        except Exception:
            pass
    if hasattr(self, "bins"):
        # Ensure bins is a list after reset
        if not isinstance(self.bins, list):
            self.bins = list(self.bins) if self.bins is not None else []
    return None

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Retrieve the error indices container
    err_indices = getattr(self, "_err_indices", None)
    if err_indices is None:
        raise AttributeError("The object has no attribute '_err_indices'")

    # Determine indices based on the type of err_indices
    if isinstance(err_indices, dict):
        try:
            indices = err_indices[coord_name]
        except KeyError:
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices")
    elif isinstance(err_indices, (list, tuple)):
        # Expect a parallel list of coordinate names
        coord_names = getattr(self, "_coord_names", None)
        if coord_names is None:
            raise AttributeError("The object has no attribute '_coord_names'")
        try:
            idx = coord_names.index(coord_name)
        except ValueError:
            raise KeyError(f"Coordinate '{coord_name}' not found in coordinate names")
        try:
            indices = err_indices[idx]
        except IndexError:
            raise IndexError(f"Error indices list does not contain entry for coordinate '{coord_name}'")
    else:
        raise TypeError("_err_indices must be a dict or a list/tuple")

    # Normalise the result to a list of indices
    if indices is None:
        return []

    # If it's already a list or tuple, return a copy
    if isinstance(indices, (list, tuple)):
        return list(indices)

    # Try to iterate over it (handles numpy arrays, generators, etc.)
    try:
        return list(indices)
    except TypeError:
        # Not iterable; treat as a single index
        return [indices]

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert bins to a nested list structure
    try:
        bins_list = list(bins)
    except TypeError:
        # bins is not iterable (e.g., scalar), treat as single value
        bins_list = bins

    # Helper to compute widths for each dimension
    def compute_widths(e):
        e_list = list(e)
        if len(e_list) < 2:
            raise ValueError("Edge array must contain at least two points.")
        return [e_list[i + 1] - e_list[i] for i in range(len(e_list) - 1)]

    # 1D case
    if not isinstance(edges, (list, tuple)):
        widths = compute_widths(edges)
        if len(bins_list) != len(widths):
            raise ValueError("Number of bins does not match number of edges.")
        return sum(b * w for b, w in zip(bins_list, widths))

    # Multi-dimensional case
    widths = [compute_widths(e) for e in edges]
    # Recursive integration over nested lists
    def rec(b, w, dim):
        if dim == len(w):
            # Reached the innermost value
            return b
        if len(b) != len(w[dim]):
            raise ValueError(f"Dimension {dim} size mismatch between bins and edges.")
        total = 0
        for i, val in enumerate(b):
            total += rec(val, w, dim + 1) * w[dim][i]
        return total

    return rec(bins_list, widths, 0)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        if seq is None:
            return False
        if isinstance(seq, FillRequest):
            return True
        if isinstance(seq, Source):
            return False
        if isinstance(seq, (str, bytes)):
            return False
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except Exception:
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    if obj is None:
        return False
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
