def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict):
        raise TypeError(f"d1 must be a dict, got {type(d1).__name__}")
    if not isinstance(d2, dict):
        raise TypeError(f"d2 must be a dict, got {type(d2).__name__}")
    if not isinstance(level, int):
        raise TypeError(f"level must be an int, got {type(level).__name__}")
    if level < -1:
        raise ValueError("level must be -1 (infinite) or a non-negative integer")

    def _diff(sub_d1, sub_d2, cur_level):
        """Recursively compute difference for sub-dictionaries."""
        result = {}
        for key, val1 in sub_d1.items():
            if key not in sub_d2:
                # Key only in d1: include it
                result[key] = val1
            else:
                val2 = sub_d2[key]
                # If both values are dicts and we can recurse
                if isinstance(val1, dict) and isinstance(val2, dict):
                    # Determine next recursion level
                    if cur_level == -1:
                        next_level = -1
                    else:
                        next_level = cur_level - 1
                    # Recurse only if we are allowed to go deeper
                    if next_level != 0:
                        sub_diff = _diff(val1, val2, next_level)
                        if sub_diff:
                            result[key] = sub_diff
                    else:
                        # At level 0, treat dicts as values; include if not equal
                        if val1 != val2:
                            result[key] = val1
                else:
                    # For non-dict values or mismatched types
                    if val1 != val2:
                        result[key] = val1
        return result

    # Compute the difference
    diff_result = _diff(d1, d2, level)

    # If the result is empty, return an empty dict
    if not diff_result:
        return {}
    return diff_result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception:
        raise TypeError("weight must be a numeric value")

    # Validate and normalize coord
    if isinstance(coord, (int, float)):
        coord = [coord]
    elif isinstance(coord, str):
        raise TypeError("coord must be a number or an iterable of numbers")
    else:
        try:
            coord = list(coord)
        except Exception:
            raise TypeError("coord must be a number or an iterable of numbers")

    # Retrieve edges
    edges = getattr(self, 'edges', None)
    if edges is None:
        raise AttributeError("Histogram has no 'edges' attribute")

    # Normalize edges to a list of sequences
    if isinstance(edges, (list, tuple)):
        # If each element is a sequence, treat as multi-dimensional edges
        if all(isinstance(e, (list, tuple)) for e in edges):
            edges_list = list(edges)
        else:
            edges_list = [edges]
    else:
        edges_list = [edges]

    if len(edges_list) != len(coord):
        raise ValueError("coord dimension does not match histogram dimensions")

    # Find bin indices
    indices = []
    for dim, (edge, c) in enumerate(zip(edges_list, coord)):
        if not isinstance(edge, (list, tuple)):
            raise TypeError(f"Edge for dimension {dim} must be a sequence")
        if len(edge) < 2:
            raise ValueError(f"Edge for dimension {dim} must have at least two boundaries")
        idx = None
        for i in range(len(edge) - 1):
            if edge[i] <= c < edge[i + 1]:
                idx = i
                break
        if idx is None:
            # Coordinate is outside the histogram edges; ignore
            return
        indices.append(idx)

    # Increment the appropriate bin
    bins = getattr(self, 'bins', None)
    if bins is None:
        raise AttributeError("Histogram has no 'bins' attribute")
    try:
        bins[tuple(indices)] += weight
    except Exception:
        # Fallback to nested indexing for list-of-lists structures
        try:
            b = bins
            for idx in indices[:-1]:
                b = b[idx]
            b[indices[-1]] += weight
        except Exception as e:
            raise RuntimeError(f"Failed to increment bin: {e}")

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    if not isinstance(labels, dict):
        raise TypeError("labels must be a dict")

    # Helper functions to validate keys and values according to Kubernetes label rules.
    def _is_valid_label_key(key_str):
        if not key_str:
            return False
        # Must start and end with an alphanumeric character.
        if not (key_str[0].isalnum() and key_str[-1].isalnum()):
            return False
        # Allowed characters: alphanumeric, '.', '-', '_'
        for ch in key_str:
            if not (ch.isalnum() or ch in "._-"):
                return False
        return True

    def _is_valid_label_value(value_str):
        if not value_str:
            return False
        if not (value_str[0].isalnum() and value_str[-1].isalnum()):
            return False
        for ch in value_str:
            if not (ch.isalnum() or ch in "._-"):
                return False
        return True

    # Regex pattern string used in error messages (not used for actual matching).
    pattern_str = "^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$"

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not _is_valid_label_key(key_str):
                errors.append(
                    {key_str: f"Label key '{key_str}' does not match the regex [{pattern_str}]"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            value_str = value.decode() if isinstance(value, bytes) else value
            if not _is_valid_label_value(value_str):
                errors.append(
                    {value_str: f"Label value '{value_str}' does not match the regex [{pattern_str}]"}
                )

    if errors:
        raise ValidationError(errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list from a partial
    Kubernetes response.

    Args:
        last_applied_manifest (list): Partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): Partial ``observer_schema`` describing the
            expected fields.
        response (list): Partial response from the Kubernetes API.

    Returns:
        list: The updated ``last_applied_manifest`` list.
    """
    # Basic validation
    if not isinstance(observer_schema, list) or not isinstance(response, list):
        return last_applied_manifest or []

    # Ensure we have a list to work with
    if last_applied_manifest is None:
        last_applied_manifest = []

    # Extend the manifest list to match the response length if needed
    if len(last_applied_manifest) < len(response):
        last_applied_manifest.extend([{} for _ in range(len(response) - len(last_applied_manifest))])

    # Iterate over each item in the response
    for idx, resp_item in enumerate(response):
        if not isinstance(resp_item, dict):
            continue

        # Ensure the corresponding manifest item is a dict
        if not isinstance(last_applied_manifest[idx], dict):
            last_applied_manifest[idx] = {}

        manifest_item = last_applied_manifest[idx]

        # Iterate over each field descriptor in the observer schema
        for field in observer_schema:
            if not isinstance(field, dict):
                continue

            name = field.get("name")
            if not name:
                continue

            # Initialize the field if it is missing
            if name not in manifest_item:
                # Prefer the value from the response if available
                if name in resp_item:
                    manifest_item[name] = resp_item[name]
                else:
                    # Default to None; will be overwritten by recursion if needed
                    manifest_item[name] = None

            # Handle nested structures
            ftype = field.get("type")
            children = field.get("children", [])

            if ftype == "list":
                # Ensure the field is a list
                if not isinstance(manifest_item.get(name), list):
                    manifest_item[name] = []
                child_resp = resp_item.get(name, [])
                if not isinstance(child_resp, list):
                    child_resp = []
                update_last_applied_manifest_list_from_resp(
                    manifest_item[name], children, child_resp
                )
            elif ftype == "dict":
                # Ensure the field is a dict
                if not isinstance(manifest_item.get(name), dict):
                    manifest_item[name] = {}
                child_resp = resp_item.get(name, {})
                if not isinstance(child_resp, dict):
                    child_resp = {}
                # The dict update function is assumed to exist in the same module
                update_last_applied_manifest_dict_from_resp(
                    manifest_item[name], children, child_resp
                )

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource identifiers (kind/name) to the generated default
              observer schema. Resources that already have a custom observer schema are
              omitted from the result.

    Raises:
        ValueError: If ``app`` or its required attributes are missing or invalid.
    """
    # Helper to safely get an attribute or dict key
    def _get(obj, key, default=None):
        if obj is None:
            return default
        if isinstance(obj, dict):
            return obj.get(key, default)
        return getattr(obj, key, default)

    # Validate input
    if app is None:
        raise ValueError("app must not be None")
    spec = _get(app, "spec")
    if spec is None:
        raise ValueError("app.spec must not be None")
    manifest = _get(spec, "manifest")
    if manifest is None:
        raise ValueError("app.spec.manifest must not be None")
    if not isinstance(manifest, (list, tuple)):
        raise ValueError("app.spec.manifest must be a list or tuple of resources")

    default_schemas = {}
    for idx, resource in enumerate(manifest):
        # Skip if custom observer schema already defined
        custom_schema = _get(resource, "observer_schema")
        if custom_schema is not None:
            continue

        # Extract basic fields
        api_version = _get(resource, "apiVersion", "")
        kind = _get(resource, "kind", "")
        metadata = _get(resource, "metadata", {})
        name = _get(metadata, "name", f"{kind}-{idx}")
        namespace = _get(metadata, "namespace", None)

        # Build a minimal default observer schema
        schema = {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {
                "name": name,
            },
        }
        if namespace is not None:
            schema["metadata"]["namespace"] = namespace

        # Optionally include spec and status placeholders
        schema["spec"] = {}
        schema["status"] = {}

        # Use a unique key for the resource
        key = f"{kind}/{name}"
        default_schemas[key] = schema

    return default_schemas

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    # Determine if sql is bytes or str
    is_bytes = isinstance(sql, bytes)
    sql_str = sql.decode() if is_bytes else sql

    # Determine styles
    in_style = getattr(self, "in_style", None)
    out_style = getattr(self, "out_style", None)
    if in_style is None or out_style is None:
        raise AttributeError("in_style and out_style must be defined on self")

    # Helper to check named style
    def is_named(style: str) -> bool:
        return style in (":", "@", "$")

    named_in = is_named(in_style)
    named_out = is_named(out_style)

    # If styles are identical, no conversion needed
    if in_style == out_style:
        # Ensure many_params is a list
        new_params = list(many_params)
        return (sql, new_params)

    # Build regex pattern for placeholders
    import re
    if named_in:
        # Named placeholder: e.g., :name
        pattern = re.compile(r"(?<![\\])" + re.escape(in_style) + r"(\w+)")
    else:
        # Ordinal placeholder: e.g., ?
        pattern = re.compile(r"\?")

    # Find all placeholders
    matches = list(pattern.finditer(sql_str))
    if named_in:
        placeholder_names = [m.group(1) for m in matches]
    else:
        placeholder_names = list(range(1, len(matches) + 1))

    # Replace placeholders with out_style
    counter = 0

    def repl(m):
        nonlocal counter
        if named_in:
            name = m.group(1)
            if named_out:
                return out_style + name
            else:
                return out_style
        else:
            counter += 1
            if named_out:
                return out_style + str(counter)
            else:
                return out_style

    new_sql_str = pattern.sub(repl, sql_str)

    # Convert parameters
    new_params = []
    for p in many_params:
        # Validate type
        if named_in:
            if not isinstance(p, dict):
                raise TypeError("Expected mapping for named parameters")
            if named_out:
                # Keep mapping as is (keys unchanged)
                new_params.append(dict(p))
            else:
                # Convert to list of values in order of placeholder names
                try:
                    values = [p[name] for name in placeholder_names]
                except KeyError as e:
                    raise KeyError(f"Missing parameter {e.args[0]} in params") from None
                new_params.append(values)
        else:
            # Ordinal parameters
            if not isinstance(p, (list, tuple)):
                raise TypeError("Expected sequence for ordinal parameters")
            if named_out:
                if len(p) != len(placeholder_names):
                    raise ValueError("Number of parameters does not match number of placeholders")
                mapping = {i + 1: p[i] for i in range(len(p))}
                new_params.append(mapping)
            else:
                # Keep list as is
                new_params.append(list(p))

    # Encode back to bytes if needed
    new_sql = new_sql_str.encode() if is_bytes else new_sql_str
    return (new_sql, new_params)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Convert to a string path if possible
        if hasattr(path, "__fspath__"):
            path_str = path.__fspath__()
        else:
            path_str = str(path)

        # Check that the path exists and is a directory
        try:
            with open(path_str, "r") as _:
                # If we can open it as a file, it's not a directory
                return False
        except IsADirectoryError:
            # It's a directory – continue
            pass
        except FileNotFoundError:
            return False
        except Exception:
            return False

        # Check for the required .ocfl_version file
        try:
            with open(path_str + "/.ocfl_version", "r") as f:
                version = f.read().strip()
                if not version:
                    return False
        except FileNotFoundError:
            return False
        except Exception:
            return False

        # Check that the 'objects' directory exists
        try:
            with open(path_str + "/objects", "r") as _:
                # If we can open it as a file, it's not a directory
                return False
        except IsADirectoryError:
            # It's a directory – good
            pass
        except FileNotFoundError:
            return False
        except Exception:
            return False

        # All basic checks passed
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Attempt to locate the validation log attribute
    log = None
    for attr in ('validation_log', '_validation_log', 'log', '_log'):
        if hasattr(self, attr):
            log = getattr(self, attr)
            break
    if log is None:
        return ''
    # If the log is a string, treat it as a single entry
    if isinstance(log, str):
        log = [log]
    # Ensure the log is iterable
    try:
        iter(log)
    except TypeError:
        # Not iterable; return its string representation with prefix
        return f"{prefix}{str(log)}"
    # Build the prefixed lines
    lines = []
    for entry in log:
        lines.append(f"{prefix}{str(entry)}")
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type checks
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a dictionary")

        # Determine spec version
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            type_val = inventory.get("type")
            if type_val is None:
                # No type provided; fall back to self.spec_version
                if spec_version is None:
                    raise ValueError("spec_version not set and inventory has no type")
            else:
                if not isinstance(type_val, str):
                    raise ValueError("inventory type must be a string")
                # Map type to spec version (example mapping)
                type_to_version = {
                    "v1": "1.0",
                    "v2": "2.0",
                    "v3": "3.0",
                }
                if type_val not in type_to_version:
                    # Unknown type; fall back to self.spec_version
                    if spec_version is None:
                        raise ValueError(f"unknown inventory type '{type_val}' and spec_version not set")
                else:
                    spec_version = type_to_version[type_val]

        if spec_version is None:
            raise ValueError("spec_version could not be determined")

        # Example validation rules based on spec_version
        # These are placeholders; real rules would be more complex
        if spec_version == "1.0":
            required_keys = {"name", "items"}
            if not required_keys.issubset(inventory):
                missing = required_keys - inventory.keys()
                raise ValueError(f"inventory missing required keys for spec 1.0: {missing}")
            if not isinstance(inventory["items"], list):
                raise ValueError("inventory 'items' must be a list for spec 1.0")
        elif spec_version == "2.0":
            required_keys = {"id", "components"}
            if not required_keys.issubset(inventory):
                missing = required_keys - inventory.keys()
                raise ValueError(f"inventory missing required keys for spec 2.0: {missing}")
            if not isinstance(inventory["components"], list):
                raise ValueError("inventory 'components' must be a list for spec 2.0")
        else:
            # For unknown spec versions, perform minimal checks
            if "name" not in inventory:
                raise ValueError("inventory must contain a 'name' key")

        # If all checks pass, return True
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Normalize digests_used to a set
        try:
            used_set = set(digests_used)
        except TypeError:
            raise TypeError("digests_used must be an iterable of digests")

        # Extract digests from manifest_files
        manifest_digests = set()
        if isinstance(manifest_files, dict):
            # Assume values are digests
            for key, value in manifest_files.items():
                if isinstance(value, (str, bytes)):
                    manifest_digests.add(value)
                else:
                    # Try to get 'digest' key if value is a dict
                    if isinstance(value, dict) and 'digest' in value:
                        manifest_digests.add(value['digest'])
                    else:
                        raise ValueError(f"Unsupported manifest entry for key {key}: {value}")
        elif isinstance(manifest_files, (list, tuple)):
            for entry in manifest_files:
                if isinstance(entry, dict):
                    if 'digest' in entry:
                        manifest_digests.add(entry['digest'])
                    else:
                        raise ValueError(f"Manifest entry missing 'digest' key: {entry}")
                else:
                    raise ValueError(f"Unsupported manifest entry type: {entry}")
        else:
            raise TypeError("manifest_files must be a dict or a list/tuple of dicts")

        # Check that all used digests are present in the manifest
        missing_in_manifest = used_set - manifest_digests
        if missing_in_manifest:
            raise ValueError(f"Digests used but not present in manifest: {sorted(missing_in_manifest)}")

        # Check that all digests in the manifest are used
        unused_in_manifest = manifest_digests - used_set
        if unused_in_manifest:
            raise ValueError(f"Digests present in manifest but not used: {sorted(unused_in_manifest)}")

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Both inventories must expose a 'version' attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError(
            "Both inventories must have a 'version' attribute for comparison"
        )

    # The prior version must be strictly older
    if prior.version >= self.version:
        raise ValueError(
            f"Prior version {prior.version} is not older than current version {self.version}"
        )

    # If both inventories expose an 'items' mapping, ensure the prior's items
    # are a subset of the current inventory's items.
    if hasattr(self, "items") and hasattr(prior, "items"):
        if not isinstance(self.items, dict) or not isinstance(prior.items, dict):
            raise TypeError(
                "The 'items' attribute must be a dictionary in both inventories"
            )
        missing_keys = set(prior.items) - set(self.items)
        if missing_keys:
            raise ValueError(
                f"Current inventory is missing items present in prior: {missing_keys}"
            )

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if inventory is None:
        raise TypeError("inventory must not be None")
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or a list")

    # Prepare result dictionary
    result = {}

    # Helper to add a content file to the mapping
    def _add(logical_path, content_file):
        if logical_path not in result:
            result[logical_path] = set()
        result[logical_path].add(content_file)

    # Process dictionary inventory: {version: {logical_path: content_file}}
    if isinstance(inventory, dict):
        for ver_key, paths in inventory.items():
            # Skip if version key is not comparable
            try:
                if ver_key < version:
                    continue
            except Exception:
                continue
            if not isinstance(paths, dict):
                continue
            for logical_path, content_file in paths.items():
                if content_file is None:
                    continue
                _add(logical_path, content_file)

    # Process list inventory: list of entries with keys 'version', 'logical_path', 'content_file'
    elif isinstance(inventory, list):
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            ver_key = entry.get("version")
            logical_path = entry.get("logical_path")
            content_file = entry.get("content_file")
            if logical_path is None or content_file is None:
                continue
            try:
                if ver_key < version:
                    continue
            except Exception:
                continue
            _add(logical_path, content_file)

    return result

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.

    Parameters
    ----------
    fixity : dict
        The fixity block from the inventory. Expected to contain a 'files'
        key mapping to a dictionary of file entries.
    manifest_files : Iterable[str]
        Collection of file names that are present in the manifest.

    Raises
    ------
    ValueError
        If the fixity block is malformed or references files not in the
        manifest, or if required fields are missing.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files_dict = fixity['files']
    if not isinstance(files_dict, dict):
        raise ValueError("'files' key must map to a dictionary")

    # Normalize manifest files to a set for fast lookup
    if manifest_files is None:
        manifest_set = set()
    else:
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise ValueError("manifest_files must be an iterable of file names")

    for fname, entry in files_dict.items():
        if fname not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{fname}' not present in manifest")

        if not isinstance(entry, dict):
            raise ValueError(f"Entry for file '{fname}' must be a dictionary")

        # Required fields for each file entry
        required_fields = {'checksum', 'size'}
        missing = required_fields - entry.keys()
        if missing:
            raise ValueError(f"Entry for file '{fname}' missing required fields: {', '.join(missing)}")

        # Basic type checks
        if not isinstance(entry['checksum'], str):
            raise ValueError(f"Checksum for file '{fname}' must be a string")
        if not isinstance(entry['size'], int):
            raise ValueError(f"Size for file '{fname}' must be an integer")

    # If all checks pass, return True
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os

    # Validate input type
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")

    # Check existence
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")

    # Ensure it's a directory
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")

    try:
        entries = os.listdir(path)
    except PermissionError as e:
        raise PermissionError(f"Permission denied when accessing {path}") from e
    except OSError as e:
        raise OSError(f"Error accessing {path}: {e}") from e

    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        try:
            if os.path.isfile(full_path):
                files.append(entry)
        except OSError:
            # Skip entries that cannot be accessed
            continue

    return files

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Identify basenames that have an XML file
            xml_basenames = set()
            for name in zf.namelist():
                # Skip directories
                if name.endswith('/'):
                    continue
                if name.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(name))[0]
                    xml_basenames.add(base)

            result = {}
            for name in zf.namelist():
                if name.endswith('/'):
                    continue
                base = os.path.splitext(os.path.basename(name))[0]
                if base in xml_basenames:
                    with zf.open(name) as f:
                        content = f.read()
                    result.setdefault(base, {})[name] = content
            return result
    except zipfile.BadZipFile as exc:
        raise ValueError(f"Invalid zip file: {zip_path}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error processing zip file {zip_path}: {exc}") from exc

