def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
        except Exception:
            continue
        if not result:
            continue
        # If result is a list, take the first element
        if isinstance(result, list):
            first = result[0]
        else:
            first = result
        # If the first element is an lxml element, get its text content
        if hasattr(first, "text_content"):
            try:
                text = first.text_content()
            except Exception:
                text = None
        elif hasattr(first, "text"):
            try:
                text = first.text
            except Exception:
                text = None
        else:
            text = str(first)
        if text is None:
            continue
        text = text.strip()
        if text:
            return text
    return None

