def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate hook
    if hook is None:
        raise ValueError("hook must not be None")
    # Ensure registry exists
    if not hasattr(self, "_registry"):
        self._registry = {}
    # Ensure hook key exists
    try:
        if hook not in self._registry:
            self._registry[hook] = []
    except TypeError as exc:
        raise TypeError(f"hook {hook!r} is not hashable") from exc

    def decorator(func):
        if not callable(func):
            raise TypeError("handler must be callable")
        # Avoid duplicate registration
        if func in self._registry[hook]:
            return func
        self._registry[hook].append(func)
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    try:
        # In Python 2, 'unicode' is defined; in Python 3 it is not.
        unicode
    except NameError:
        # Python 3: no conversion needed, return the original function.
        return namefunc
    else:
        # Python 2: wrap the function to encode unicode results to bytes.
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except Exception as e:
                    raise ValueError("Failed to encode unicode result to bytes: %s" % e)
            return result
        return wrapper

