def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands] + list(args)
    else:
        cmd = list(commands) + list(args)

    # Prepare environment
    if env is not None:
        env = {**os.environ, **env}
    else:
        env = os.environ

    # Verbose output
    if verbose:
        print("Running command:", " ".join(cmd))

    # Set stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            stderr=stderr_option,
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        # If stderr was hidden, we still want to show the error message
        error_msg = e.stderr if e.stderr else ""
        raise RuntimeError(
            f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}. "
            f"Error output: {error_msg}"
        ) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command '{' '.join(cmd)}': {e}") from e

