def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    # Attempt to retrieve the objects from the storage root
    try:
        objects_iter = self.get_objects()
    except Exception as exc:
        raise RuntimeError("Failed to retrieve objects from storage root") from exc

    # Ensure we have an iterable
    if objects_iter is None:
        raise RuntimeError("get_objects() returned None, expected an iterable of objects")
    try:
        # Try to iterate to confirm it's iterable
        iter(objects_iter)
    except TypeError as exc:
        raise RuntimeError("get_objects() did not return an iterable") from exc

    num_objects = 0
    good_objects = 0

    for obj in objects_iter:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    if not obj.validate():
                        is_valid = False
                else:
                    if show_warnings:
                        print(f"Warning: object {obj!r} has no 'validate' method")
                    is_valid = False
            except Exception as exc:
                if show_warnings:
                    print(f"Warning: validation failed for object {obj!r}: {exc}")
                is_valid = False

        # Check the digest if requested and the object passed previous checks
        if check_digests and is_valid:
            try:
                if hasattr(obj, "check_digest"):
                    if not obj.check_digest():
                        is_valid = False
                else:
                    if show_warnings:
                        print(f"Warning: object {obj!r} has no 'check_digest' method")
                    is_valid = False
            except Exception as exc:
                if show_warnings:
                    print(f"Warning: digest check failed for object {obj!r}: {exc}")
                is_valid = False

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate input
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list of directory names")
    if not all(isinstance(v, str) for v in version_dirs):
        raise TypeError("All items in version_dirs must be strings")

    # Ensure root inventory is available
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("root_inventory attribute must be a dictionary")

    # Prepare a dictionary to record differences
    self.different_digests = {}

    for version_dir in version_dirs:
        # Build path to the inventory file
        inventory_path = os.path.join(version_dir, "inventory.json")

        # Check that the inventory file exists
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(f"Inventory file not found in directory '{version_dir}'")

        # Load the inventory JSON
        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                inventory = json.load(f)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON in inventory '{inventory_path}': {exc}") from exc

        # Inventory must be a mapping of content paths to digests
        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory '{inventory_path}' must be a JSON object (dict)")

        # Compare each digest to the root inventory
        for content_path, digest in inventory.items():
            root_digest = self.root_inventory.get(content_path)
            if root_digest is None:
                # Content not present in root; skip comparison
                continue
            if digest != root_digest:
                self.different_digests.setdefault(content_path, []).append(version_dir)

    return self.different_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids is None:
        return params
    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, (list, tuple, set)):
        bug_id_list = [str(b).strip() for b in bug_ids if b is not None]
    elif isinstance(bug_ids, str):
        bug_id_list = [b.strip() for b in bug_ids.split(',') if b.strip()]
    else:
        bug_id_list = [str(bug_ids).strip()]
    # Merge with existing 'ids' key
    existing = params.get('ids')
    if existing is None:
        params['ids'] = ','.join(bug_id_list)
    else:
        if isinstance(existing, str):
            existing_list = [b.strip() for b in existing.split(',') if b.strip()]
        elif isinstance(existing, (list, tuple, set)):
            existing_list = [str(b).strip() for b in existing]
        else:
            existing_list = []
        combined = list(dict.fromkeys(existing_list + bug_id_list))
        params['ids'] = ','.join(combined)
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper functions
    def is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    def merge_nodes(node1, node2):
        if is_mapping_node(node1) and is_mapping_node(node2):
            return merge_mapping_nodes(node1, node2)
        # last wins
        return node2

    def merge_mapping_nodes(node1, node2):
        # Build a dict of key -> (key_node, value_node) from node1
        mapping = {}
        for k_node, v_node in getattr(node1, 'value', []):
            mapping[k_node.value] = (k_node, v_node)
        # Merge entries from node2
        for k_node, v_node in getattr(node2, 'value', []):
            key = k_node.value
            if key in mapping:
                existing_k_node, existing_v_node = mapping[key]
                merged_v_node = merge_nodes(existing_v_node, v_node)
                mapping[key] = (existing_k_node, merged_v_node)
            else:
                mapping[key] = (k_node, v_node)
        # Build merged list preserving order: first node1 order, then new keys from node2
        merged_list = []
        seen_keys = set()
        for k_node, v_node in getattr(node1, 'value', []):
            key = k_node.value
            merged_list.append(mapping[key])
            seen_keys.add(key)
        for k_node, v_node in getattr(node2, 'value', []):
            key = k_node.value
            if key not in seen_keys:
                merged_list.append(mapping[key])
        # Update node1's value list
        node1.value = merged_list
        return node1

    # Validate input
    if not hasattr(nodes, '__iter__'):
        raise TypeError('nodes must be an iterable of (key_node, value_node) tuples')
    result = []
    key_index = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each element of nodes must be a tuple of (key_node, value_node)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError('key_node must have a value attribute')
        key = key_node.value
        if key in key_index:
            existing_value_node = result[key_index[key]][1]
            merged_value_node = merge_nodes(existing_value_node, value_node)
            result[key_index[key]] = (key_node, merged_value_node)
        else:
            result.append((key_node, value_node))
            key_index[key] = len(result) - 1
    return result

def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    import argparse
    parser = argparse.ArgumentParser()
    # If no arguments are provided, parse sys.argv[1:]
    if not arguments:
        try:
            return parser.parse_args()
        except SystemExit as e:
            raise ValueError(f"Argument parsing failed: {e}") from e
    # Flatten arguments and ensure all items are strings
    args_list = []
    for arg in arguments:
        if isinstance(arg, (list, tuple)):
            args_list.extend(map(str, arg))
        else:
            args_list.append(str(arg))
    try:
        return parser.parse_args(args_list)
    except SystemExit as e:
        raise ValueError(f"Argument parsing failed: {e}") from e

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError("parser cannot be None")
    # Basic check for an ArgumentParser-like object
    if not hasattr(parser, '_actions') or not hasattr(parser, 'add_argument'):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    try:
        for action in parser._actions:
            opt_strings = getattr(action, 'option_strings', None)
            if not opt_strings:
                continue
            # Ensure we are iterating over a collection of strings
            if isinstance(opt_strings, (list, tuple, set)):
                for opt in opt_strings:
                    if isinstance(opt, str) and opt:
                        flags.append(opt)
            else:
                # Skip non-iterable or unexpected types
                continue
    except Exception as exc:
        raise RuntimeError(f"Error while extracting flags: {exc}") from exc
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Import argparse lazily to avoid top‑level import statements
    argparse = __import__('argparse')
    parser = argparse.ArgumentParser()
    try:
        # Use parse_known_args to avoid SystemExit on unknown arguments
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        raise ValueError(f"Error parsing arguments: {exc}") from exc
    # Since we don't know the subparsers, return the global namespace
    return {"global": namespace}

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (key_node, value_node) tuples')
    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'
    # Helper to merge two values
    def merge_values(a, b):
        if is_mapping(a) and is_mapping(b):
            # Merge mapping nodes recursively
            merged_pairs = deep_merge_nodes(a.value + b.value)
            # Create a new MappingNode with the same tag as a
            return type(a)(tag=a.tag, value=merged_pairs)
        # If either is not a mapping, last wins
        return b
    merged_dict = {}
    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            raise TypeError('key_node must have a value attribute')
        key = key_node.value
        if key in merged_dict:
            existing_key_node, existing_value_node = merged_dict[key]
            merged_value_node = merge_values(existing_value_node, value_node)
            merged_dict[key] = (existing_key_node, merged_value_node)
        else:
            merged_dict[key] = (key_node, value_node)
    # Preserve insertion order
    return list(merged_dict.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")
    # Basic check for argparse.ArgumentParser by presence of _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    try:
        for action in parser._actions:
            # Some actions may not have option_strings (e.g., positional arguments)
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                # Ensure each option string is a string
                for opt in option_strings:
                    if isinstance(opt, str):
                        flags.append(opt)
                    else:
                        flags.append(str(opt))
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc
    return " ".join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Normalise inputs
    if unparsed_arguments is None:
        unparsed_arguments = []
    try:
        unparsed_list = list(unparsed_arguments)
    except Exception as exc:
        raise TypeError("unparsed_arguments must be an iterable of strings") from exc

    if subparsers is None:
        subparsers = {}
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")

    parsed_dict = {}
    recognized_set = set()

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Parser for subparser '{name}' does not have a parse_known_args method")
        try:
            namespace, remaining = parser.parse_known_args(unparsed_list)
        except SystemExit:
            # Skip this parser if it fails to parse (e.g., missing required args)
            continue
        parsed_dict[name] = namespace

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    for start in range(0, len(response), max_results):
        yield response[start:start + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError("All items in dicts must be dictionaries")
        for k, v in d.items():
            if not isinstance(v, (int, float)):
                raise TypeError(f"Values must be numeric, got {type(v)} for key {k}")
            result[k] = result.get(k, 0) + v
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if not isinstance(val, str):
        return False
    stripped = val.strip().lower()
    return stripped in {"none", "null", "nil"}

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")
    if not all(isinstance(ch, str) for ch in alphabet):
        raise TypeError("all elements of alphabet must be strings")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct characters")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding if requested
    if padding is not None and padding > len(digits):
        pad_len = padding - len(digits)
        digits = [alphabet[0]] * pad_len + digits

    return "".join(digits)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    result = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        try:
            subs = parent.__subclasses__()
        except Exception:
            continue
        for sub in subs:
            if sub not in result:
                result.add(sub)
                stack.append(sub)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate types
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list) or not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must be a list of str")

    # Alphabet must not be empty
    if len(alphabet) == 0:
        raise ValueError("alphabet cannot be empty")

    # Alphabet elements must be single characters and unique
    if any(len(x) != 1 for x in alphabet):
        raise ValueError("each alphabet element must be a single character")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate symbols")

    # Empty string is not a valid number representation
    if string == "":
        raise ValueError("string cannot be empty")

    # Build mapping from symbol to digit value
    mapping = {char: idx for idx, char in enumerate(alphabet)}
    base = len(alphabet)

    # Convert
    result = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"character '{ch}' not in alphabet")
        result = result * base + mapping[ch]

    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove leading or trailing single or double quotes
    return re.sub(r"^['\"]|['\"]$", "", name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    # Determine platform
    if platform == 'this':
        # Default to POSIX on unknown platform
        platform = 1
    if platform not in (0, 1):
        raise ValueError(f"Unsupported platform value: {platform!r}")

    # Helper for POSIX splitting
    def _posix_split(cmd):
        args = []
        i = 0
        n = len(cmd)
        while i < n:
            # Skip leading whitespace
            while i < n and cmd[i].isspace():
                i += 1
            if i >= n:
                break
            arg = []
            in_single = False
            in_double = False
            while i < n:
                c = cmd[i]
                if in_single:
                    if c == "'":
                        in_single = False
                    else:
                        arg.append(c)
                    i += 1
                elif in_double:
                    if c == '"':
                        in_double = False
                        i += 1
                    elif c == '\\':
                        i += 1
                        if i < n:
                            arg.append(cmd[i])
                            i += 1
                        else:
                            arg.append('\\')
                    else:
                        arg.append(c)
                        i += 1
                else:
                    if c.isspace():
                        break
                    elif c == "'":
                        in_single = True
                        i += 1
                    elif c == '"':
                        in_double = True
                        i += 1
                    elif c == '\\':
                        i += 1
                        if i < n:
                            arg.append(cmd[i])
                            i += 1
                        else:
                            arg.append('\\')
                    else:
                        arg.append(c)
                        i += 1
            if in_single or in_double:
                raise ValueError("unterminated quote in command")
            args.append(''.join(arg))
        return args

    # Helper for Windows splitting
    def _windows_split(cmd):
        args = []
        i = 0
        n = len(cmd)
        while i < n:
            # Skip leading whitespace
            while i < n and cmd[i].isspace():
                i += 1
            if i >= n:
                break
            arg = []
            in_quotes = False
            backslashes = 0
            while i < n:
                c = cmd[i]
                if c == '\\':
                    backslashes += 1
                    i += 1
                    continue
                if c == '"':
                    if backslashes % 2 == 0:
                        # Even number of backslashes before quote
                        arg.extend(['\\'] * (backslashes // 2))
                        in_quotes = not in_quotes
                    else:
                        # Odd number of backslashes before quote
                        arg.extend(['\\'] * (backslashes // 2))
                        arg.append('"')
                    backslashes = 0
                    i += 1
                    continue
                # If we reach here, c is not backslash or quote
                if backslashes > 0:
                    arg.extend(['\\'] * backslashes)
                    backslashes = 0
                if c.isspace() and not in_quotes:
                    break
                arg.append(c)
                i += 1
            # Append any remaining backslashes
            if backslashes > 0:
                arg.extend(['\\'] * backslashes)
            args.append(''.join(arg))
        return args

    if platform == 1:
        return _posix_split(s)
    else:
        return _windows_split(s)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str) or not host.strip():
        return False

    try:
        # Resolve the host to address info
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Host could not be resolved
        return False
    except Exception:
        # Any other unexpected error
        return False

    for entry in addr_info:
        family, _, _, _, sockaddr = entry
        try:
            if family == socket.AF_INET:
                ip = sockaddr[0]
                # IPv4 loopback range 127.0.0.0/8
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                # IPv6 loopback address
                if ip == "::1":
                    return True
        except Exception:
            # Skip malformed entries
            continue

    return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Validate matcher type
    if matcher is None:
        raise TypeError("Matcher cannot be None")
    # Accept tuple, list, or any sequence with at least one element
    if isinstance(matcher, (tuple, list)):
        if not matcher:
            raise ValueError("Matcher must contain at least a variable name")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        # If matcher is a string, treat it as the variable name with no default
        if isinstance(matcher, str):
            name = matcher
            default = None
        else:
            raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    if not isinstance(name, str):
        raise TypeError(f"Variable name must be a string, got {type(name).__name__}")

    # Retrieve from environment
    value = os.getenv(name)
    if value is not None:
        return value
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' is not set and no default value provided")

