def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if graph is None:
        raise TypeError("graph must not be None")
    if prop is None:
        raise TypeError("prop must not be None")
    if roots is not None and not isinstance(roots, set):
        raise TypeError("roots must be a set or None")

    try:
        children = set()
        parents = set()
        for child, _, parent in graph.triples((None, prop, None)):
            children.add(child)
            parents.add(parent)
    except Exception as exc:
        raise ValueError(f"Error iterating over graph triples: {exc}") from exc

    all_nodes = children | parents
    if roots is None:
        roots_set = all_nodes - children
    else:
        roots_set = {node for node in roots if node not in children}
    return roots_set

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    # Validate input
    if x is None:
        raise ValueError("Input x cannot be None")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as exc:
        raise TypeError("Input x must be a number or array-like of numbers") from exc

    mu = 0.2
    sigma = 0.1

    # Compute Gaussian
    result = np.exp(-((arr - mu) ** 2) / (2 * sigma ** 2))

    # Return scalar if input was scalar
    if np.isscalar(x):
        return float(result)
    return result

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import os
    import logging

    parsed_configs = {}
    error_records = []

    # Helper to create a LogRecord for an error
    def _log_error(msg, exc=None):
        record = logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname='',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc
        )
        error_records.append(record)

    # Attempt to import yaml if available
    try:
        import yaml
        yaml_available = True
    except Exception:
        yaml_available = False

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            _log_error(f"Failed to read configuration file '{filename}': {exc}", exc_info=exc)
            continue

        # Determine parser based on file extension
        ext = os.path.splitext(filename)[1].lower()
        try:
            if ext in {'.yaml', '.yml'} and yaml_available:
                config = yaml.safe_load(content)
            elif ext == '.json':
                config = json.loads(content)
            else:
                # Try JSON first, then YAML
                try:
                    config = json.loads(content)
                except Exception:
                    if yaml_available:
                        config = yaml.safe_load(content)
                    else:
                        raise ValueError("Unsupported file format and YAML not available")
        except Exception as exc:
            _log_error(f"Failed to parse configuration file '{filename}': {exc}", exc_info=exc)
            continue

        # Basic validation: configuration must be a dict
        if not isinstance(config, dict):
            _log_error(f"Configuration file '{filename}' does not contain a top-level dictionary")
            continue

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            # Simple shallow merge: overrides take precedence
            merged = config.copy()
            merged.update(overrides)
            config = merged

        # Resolve environment variables if requested
        if resolve_env:
            def _resolve(value):
                if isinstance(value, str):
                    return os.path.expandvars(value)
                elif isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [_resolve(v) for v in value]
                else:
                    return value
            config = _resolve(config)

        parsed_configs[filename] = config

    return parsed_configs, error_records

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        :return: Bookmarks instance
        :rtype: Bookmarks
        """
        # Validate input
        if values is None:
            raise TypeError("values must not be None")
        if isinstance(values, str):
            raise TypeError("values must be an iterable of strings, not a single string")
        try:
            iterator = iter(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        bookmarks = []
        for idx, raw in enumerate(iterator):
            if not isinstance(raw, str):
                raise TypeError(f"Bookmark at index {idx} is not a string: {raw!r}")
            try:
                # Assume Bookmark has a from_raw_value classmethod
                bookmark = Bookmark.from_raw_value(raw)
            except Exception as exc:
                raise ValueError(f"Failed to parse raw bookmark at index {idx}: {raw!r}") from exc
            if bookmark is None:
                raise ValueError(f"Parsed bookmark at index {idx} is None for raw value: {raw!r}")
            bookmarks.append(bookmark)

        # Construct the Bookmarks instance; assume the constructor accepts an iterable of Bookmark objects
        return cls(bookmarks)

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the most derived metaclass from a list of base classes and an optional explicit metaclass.
    The algorithm follows Python's rules for metaclass selection:
    - If an explicit metaclass is provided, it is considered a candidate.
    - The metaclass of each base class (i.e., type(base)) is also a candidate.
    - The most derived metaclass is the one that is a subclass of all other candidates.
    - If no candidates are found, the default metaclass `type` is returned.
    Raises TypeError if the inputs are invalid or if there is a metaclass conflict.
    """
    # Validate bases
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a sequence of classes")
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")

    # Validate explicit metaclass
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")
        if not issubclass(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a metaclass")

    # Gather candidate metaclasses
    candidates = []
    if explicit_mc is not None:
        candidates.append(explicit_mc)
    for base in bases:
        candidates.append(type(base))

    # If no candidates, default to type
    if not candidates:
        return type

    # Find the most derived metaclass
    best = None
    for cand in candidates:
        if best is None:
            best = cand
        else:
            if issubclass(cand, best):
                best = cand
            elif not issubclass(best, cand):
                raise TypeError(
                    f"metaclass conflict: {cand.__name__} and {best.__name__}"
                )
    return best

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise KeyError(key)
        return default
    del self[key]
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the container has the expected attributes
    if not hasattr(self, "key_to_val") or not self.key_to_val:
        raise KeyError("popitem from an empty container")

    # Determine the minimum frequency
    try:
        min_freq = self.min_freq
    except AttributeError:
        # Fallback: compute the minimum frequency from the key_to_freq mapping
        if not hasattr(self, "key_to_freq"):
            raise AttributeError("Missing 'key_to_freq' attribute")
        min_freq = min(self.key_to_freq.values())

    # Find a key with the minimum frequency
    key = None
    if hasattr(self, "freq_to_keys") and min_freq in self.freq_to_keys:
        keys_at_min = self.freq_to_keys[min_freq]
        try:
            key = next(iter(keys_at_min))
        except Exception:
            key = None

    if key is None:
        # Fallback: find the key with the minimum frequency directly
        if not hasattr(self, "key_to_freq"):
            raise AttributeError("Missing 'key_to_freq' attribute")
        key = min(self.key_to_freq, key=lambda k: self.key_to_freq[k])

    # Remove the key from all internal structures
    try:
        value = self.key_to_val.pop(key)
    except KeyError:
        raise KeyError(f"Key {key!r} not found in key_to_val")
    self.key_to_freq.pop(key, None)

    if hasattr(self, "freq_to_keys") and min_freq in self.freq_to_keys:
        self.freq_to_keys[min_freq].pop(key, None)
        if not self.freq_to_keys[min_freq]:
            del self.freq_to_keys[min_freq]
            # Update the minimum frequency if necessary
            if hasattr(self, "freq_to_keys") and self.freq_to_keys:
                self.min_freq = min(self.freq_to_keys)
            else:
                self.min_freq = None

    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Determine the underlying storage attribute
    storage = None
    for attr in ("cache", "_cache"):
        if hasattr(self, attr):
            storage = getattr(self, attr)
            break
    if storage is None:
        raise AttributeError("Cache storage attribute not found")
    if not storage:
        raise KeyError("popitem(): dictionary is empty")
    try:
        # For OrderedDict, popitem(last=False) returns the LRU item
        return storage.popitem(last=False)
    except TypeError:
        # Fallback for dict-like objects that don't support the `last` argument
        return storage.popitem()

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Ensure the underlying data structure exists
    if not hasattr(self, "_data"):
        raise AttributeError("The object does not have a '_data' attribute.")
    data = self._data

    # Ensure the underlying data structure supports popitem
    if not hasattr(data, "popitem"):
        raise NotImplementedError("Underlying data structure does not support popitem.")

    try:
        # Try to pop the most recently used item (last=True for OrderedDict/collections.OrderedDict)
        return data.popitem(last=True)
    except TypeError:
        # If the popitem method does not accept the 'last' keyword (e.g., plain dict in older Python),
        # fall back to the default popitem behavior which returns the last inserted item in Python 3.7+.
        try:
            return data.popitem()
        except Exception as exc:
            raise RuntimeError("Failed to pop item from the underlying data structure.") from exc
    except KeyError:
        # The underlying data structure is empty
        raise KeyError("popitem(): dictionary is empty") from None
    except Exception as exc:
        # Catch any other unexpected exceptions and re-raise with context
        raise RuntimeError("An unexpected error occurred while popping an item.") from exc

