def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Helper to determine if a message indicates a Diaspora request
        def is_diaspora_msg(msg):
            if msg is None:
                return False
            # If the message is a dictionary
            if isinstance(msg, dict):
                # Common indicators of a Diaspora payload
                if msg.get("diaspora") is not None:
                    return True
                if msg.get("type") == "diaspora":
                    return True
                if msg.get("legacy") == "diaspora":
                    return True
            else:
                # If the message is an object, check for attributes
                if getattr(msg, "diaspora", None) is not None:
                    return True
                if getattr(msg, "type", None) == "diaspora":
                    return True
                if getattr(msg, "legacy", None) == "diaspora":
                    return True
            return False

        # Safely extract fields whether request is a dict or an object
        public_msg = request.get("public_message") if isinstance(request, dict) else getattr(request, "public_message", None)
        if is_diaspora_msg(public_msg):
            return True

        private_msg = request.get("private_message") if isinstance(request, dict) else getattr(request, "private_message", None)
        if is_diaspora_msg(private_msg):
            return True

        payload = request.get("payload") if isinstance(request, dict) else getattr(request, "payload", None)
        if is_diaspora_msg(payload):
            return True

        return False
    except Exception:
        # In case of any unexpected structure or error, conservatively return False
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            # Check for typical Matrix type field
            if "type" in request and isinstance(request["type"], str):
                t = request["type"]
                if t.startswith("m.") or t.startswith("org.matrix."):
                    return True
            # Some Matrix requests may only contain a content field
            if "content" in request:
                return True

        # Handle object-like requests with attributes
        else:
            # Check for a 'type' attribute
            if hasattr(request, "type"):
                t = getattr(request, "type")
                if isinstance(t, str) and (t.startswith("m.") or t.startswith("org.matrix.")):
                    return True
            # Check for a 'content' attribute
            if hasattr(request, "content"):
                return True

    except Exception:
        # Any unexpected error should result in a safe False
        return False

    return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("tag must be a string")
    if not tag:
        return False
    if len(tag) > 30:
        return False
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-_")
    for ch in tag:
        if ch not in allowed:
            return False
    if tag[0] in "-_":
        return False
    if tag[-1] in "-_":
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception:
        return {}
    result = {}
    for child in children:
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        if not isinstance(subject, str):
            raise ValueError("JSON webfinger missing or invalid 'subject'")
        if not isinstance(aliases, list):
            raise ValueError("JSON webfinger 'aliases' must be a list")
        if not isinstance(links, list):
            raise ValueError("JSON webfinger 'links' must be a list")
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        # Fallback to XRD (XML) parsing
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            subject = None
            aliases = []
            links = []

            for elem in root.iter():
                tag = elem.tag
                # Strip namespace if present
                if "}" in tag:
                    tag = tag.split("}", 1)[1]
                if tag == "Subject":
                    subject = elem.text
                elif tag == "Alias":
                    if elem.text:
                        aliases.append(elem.text)
                elif tag == "Link":
                    rel = elem.attrib.get("rel")
                    type_ = elem.attrib.get("type")
                    href = elem.attrib.get("href")
                    link = {}
                    if rel:
                        link["rel"] = rel
                    if type_:
                        link["type"] = type_
                    if href:
                        link["href"] = href
                    links.append(link)

            if subject is None:
                raise ValueError("XRD webfinger missing 'Subject'")
            return {"subject": subject, "aliases": aliases, "links": links}
        except Exception as e:
            raise ValueError("Invalid Diaspora webfinger document") from e

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    # Basic validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("timeout must be a positive number")
    if not isinstance(method, str):
        raise ValueError("method must be a string")

    # Resolve the HTTP method function
    try:
        method_func = getattr(requests, method.lower())
    except AttributeError:
        raise ValueError(f"Unsupported HTTP method: {method}")

    try:
        # Send the request
        response = method_func(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except requests.exceptions.RequestException as exc:
        # Return None for status code and the exception instance
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    # Dynamically import required modules
    os = __import__('os')
    fnmatch = __import__('fnmatch')

    # Validate settings_dirs
    if settings_dirs is None:
        raise ValueError("settings_dirs cannot be None")
    # If a single string is provided, treat it as a single directory
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        try:
            iter(settings_dirs)
            dirs = list(settings_dirs)
        except TypeError:
            raise TypeError("settings_dirs must be a string or an iterable of directory paths")

    # Normalize spec_option
    if spec_option is None:
        patterns = [None]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        try:
            iter(spec_option)
            patterns = list(spec_option)
        except TypeError:
            raise TypeError("spec_option must be a string, None, or an iterable of patterns")

    result = []
    for dir_path in dirs:
        if not isinstance(dir_path, str):
            continue  # skip non-string entries
        if not os.path.isdir(dir_path):
            continue  # skip non-existent or non-directory paths
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                matched = False
                for pat in patterns:
                    if pat is None or fnmatch.fnmatch(entry, pat):
                        matched = True
                        break
                if matched:
                    result.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    # Return sorted list for consistency
    return sorted(result)

def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    # Attempt to import Ansible components if available
    try:
        from ansible.parsing.dataloader import DataLoader
        from ansible.inventory.manager import InventoryManager
        from ansible.vars.manager import VariableManager
        loader = DataLoader()
        inventory = InventoryManager(loader=loader)
        variable_manager = VariableManager(loader=loader)
        return {
            'loader': loader,
            'inventory': inventory,
            'variable_manager': variable_manager
        }
    except Exception:
        # Fallback: return a simple placeholder config manager
        return {
            'loader': None,
            'inventory': None,
            'variable_manager': None
        }

