def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file or file-like object
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Import yaml inside the method to avoid top-level imports
    try:
        import yaml
    except Exception as exc:
        raise IRValidatorException(f"Failed to import yaml module: {exc}")

    if yaml_file is None:
        raise IRValidatorException("yaml_file must be provided")

    # Determine if yaml_file is a file-like object or a path
    if hasattr(yaml_file, "read") and callable(yaml_file.read):
        file_obj = yaml_file
        close_file = False
    else:
        try:
            file_obj = open(yaml_file, "r")
            close_file = True
        except Exception as exc:
            raise IRValidatorException(f"Unable to open YAML file '{yaml_file}': {exc}")

    try:
        data = yaml.safe_load(file_obj)
    except Exception as exc:
        raise IRValidatorException(f"Error parsing YAML file '{yaml_file}': {exc}")
    finally:
        if close_file:
            try:
                file_obj.close()
            except Exception:
                pass  # ignore close errors

    if data is None or not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary")

    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    if not isinstance(required_fields, (list, tuple, set)):
        raise IRValidatorException("REQUIRED_FIELDS must be an iterable of field names")

    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import os
    import json

    # Basic validation of parser_dict
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    # Ensure existing groups are a dict if present
    existing_groups = parser_dict.get("groups")
    if existing_groups is not None and not isinstance(existing_groups, dict):
        raise ValueError("'groups' key must be a dictionary if present")

    # Determine base path for relative includes
    base_path = parser_dict.get("_source_path")
    if base_path:
        base_path = os.path.dirname(os.path.abspath(base_path))
    else:
        base_path = os.getcwd()

    visited_files = set()

    def _process_include(include_dict, current_base):
        if not isinstance(include_dict, dict):
            raise ValueError("'include' directive must be a dictionary")
        for group_name, file_path in include_dict.items():
            if not isinstance(group_name, str):
                raise ValueError(f"Group name must be a string, got {type(group_name).__name__}")
            if not isinstance(file_path, str):
                raise ValueError(f"File path for group '{group_name}' must be a string")

            # Resolve the file path
            full_path = (
                os.path.join(current_base, file_path)
                if not os.path.isabs(file_path)
                else file_path
            )
            full_path = os.path.abspath(full_path)

            # Avoid circular includes
            if full_path in visited_files:
                continue
            visited_files.add(full_path)

            # Load the included file
            try:
                with open(full_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except FileNotFoundError:
                raise FileNotFoundError(f"Included file not found: {full_path}")
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON in included file {full_path}: {e}")

            if not isinstance(data, dict):
                raise ValueError(f"Included file {full_path} must contain a JSON object")

            inc_groups = data.get("groups")
            if inc_groups is None:
                raise ValueError(f"No 'groups' key in included file {full_path}")
            if not isinstance(inc_groups, dict):
                raise ValueError(f"'groups' in included file {full_path} must be a dictionary")

            # Check for duplicate group names
            if group_name in parser_dict.get("groups", {}):
                raise ValueError(f"Duplicate group name '{group_name}' when including {full_path}")

            # Merge the groups
            parser_dict.setdefault("groups", {})[group_name] = inc_groups

            # Process nested includes recursively
            nested_include = data.get("include")
            if nested_include:
                _process_include(nested_include, os.path.dirname(full_path))

    include_dict = parser_dict.get("include")
    if include_dict:
        _process_include(include_dict, base_path)
        # Remove the include directive after processing
        parser_dict.pop("include", None)

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        spec = getattr(self, "spec", None)
        if spec is None:
            return {}
        if not isinstance(spec, dict):
            raise TypeError("spec must be a dictionary")
        defaults = {}
        for key, item in spec.items():
            if isinstance(item, dict):
                if "default" in item:
                    defaults[key] = item["default"]
                elif "value" in item:
                    defaults[key] = item["value"]
                else:
                    defaults[key] = None
            else:
                defaults[key] = item
        return defaults
    except Exception as exc:
        raise ValueError(f"Error resolving spec defaults: {exc}") from exc

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # This method returns a mapping of deprecated option names to their replacements.
    # If no deprecated options are defined, an empty dictionary is returned.
    return {}

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")
    if not command_name:
        raise ValueError("command_name cannot be empty")
    if not argument_name:
        raise ValueError("argument_name cannot be empty")

    # Retrieve the commands mapping
    commands = getattr(self, "commands", None)
    if commands is None:
        raise AttributeError("The object does not have a 'commands' attribute")

    # Get the command object
    command = commands.get(command_name)
    if command is None:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the options mapping from the command
    options = getattr(command, "options", None)
    if options is None:
        raise AttributeError(f"Command '{command_name}' does not have an 'options' attribute")
    if not isinstance(options, dict):
        raise TypeError(f"Options for command '{command_name}' must be a dict")

    # Get the specification for the requested argument
    spec = options.get(argument_name)
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'")

    return spec

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if args is None or not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")
    required = getattr(self, "required_args", None)
    if required is None:
        # No required arguments defined; nothing to validate
        return True
    if not isinstance(required, (set, list, tuple)):
        raise TypeError("required_args must be a set, list, or tuple of argument names")
    missing = set(required) - set(args.keys())
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(f"Missing required arguments: {missing_str}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []

    # Ensure args is a mapping for easy lookup
    if isinstance(args, (list, tuple)):
        # Convert list of tuples or list of dicts to dict
        try:
            args = dict(args)
        except Exception:
            args = {}
    elif not isinstance(args, dict):
        args = {}

    for spec in options_spec:
        # Determine spec structure
        if isinstance(spec, dict):
            name = spec.get('name')
            cond = spec.get('required_when')
        elif isinstance(spec, (list, tuple)):
            # Assume tuple format: (name, type, help, required, required_when)
            if len(spec) < 5:
                continue
            name = spec[0]
            cond = spec[4]
        else:
            continue

        if not name:
            continue

        # Evaluate condition
        matched = False
        if callable(cond):
            try:
                matched = bool(cond(args))
            except Exception:
                matched = False
        elif isinstance(cond, str):
            # Simple parsing: "key" or "key==value"
            if '==' in cond:
                key, val = cond.split('==', 1)
                key = key.strip()
                val = val.strip()
                # Try to interpret val as literal if possible
                try:
                    val_literal = eval(val, {}, {})
                except Exception:
                    val_literal = val
                matched = args.get(key) == val_literal
            else:
                key = cond.strip()
                matched = bool(args.get(key))
        else:
            # Unsupported condition type; skip
            matched = False

        if matched:
            required.append(name)

    return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a dictionary or an argument value has no length.
    :raises AttributeError: If the instance does not have a 'max_lengths' attribute.
    :raises ValueError: If any argument exceeds its specified maximum length.
    :return: True if all arguments satisfy the length constraints.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    max_lengths = getattr(self, "max_lengths", None)
    if max_lengths is None:
        raise AttributeError("Instance must have a 'max_lengths' attribute")

    for key, value in args.items():
        if key not in max_lengths:
            continue  # No length constraint for this argument

        max_len = max_lengths[key]
        if max_len is None:
            continue  # No limit specified

        if value is None:
            continue  # Treat None as acceptable

        try:
            length = len(value)
        except TypeError:
            raise TypeError(f"Argument '{key}' does not support len()")

        if length > max_len:
            raise ValueError(
                f"Argument '{key}' length {length} exceeds maximum allowed {max_len}"
            )

    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")

    # Retrieve the argument definitions; if not present, nothing to validate
    arg_defs = getattr(self, "arguments", {})
    if not isinstance(arg_defs, dict):
        raise TypeError("self.arguments must be a dictionary of argument definitions")

    for name, definition in arg_defs.items():
        # Skip if definition is not a mapping or has no choices
        if not isinstance(definition, dict):
            continue
        choices = definition.get("choices")
        if not choices:
            continue

        # Skip if the argument was not provided
        if name not in args:
            continue

        value = args[name]

        # If the value is an iterable (but not a string/bytes), validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid choice for argument '{name}': {v}. "
                        f"Available choices: {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid choice for argument '{name}': {value}. "
                    f"Available choices: {choices}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is not None
    if args is None:
        raise TypeError("args cannot be None")

    # Retrieve global min and max if defined
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    # Validate that min is not greater than max
    if min_val is not None and max_val is not None and min_val > max_val:
        raise ValueError("Minimum value cannot be greater than maximum value")

    # Helper to validate a single numeric value
    def _check_value(val, name=None):
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument value {val!r} must be a number")
        if min_val is not None and val < min_val:
            raise ValueError(
                f"Argument value {val!r} is less than minimum {min_val!r}"
            )
        if max_val is not None and val > max_val:
            raise ValueError(
                f"Argument value {val!r} is greater than maximum {max_val!r}"
            )

    # Process based on the type of args
    if isinstance(args, dict):
        for name, val in args.items():
            _check_value(val, name)
    elif isinstance(args, (list, tuple, set)):
        for val in args:
            _check_value(val)
    else:
        raise TypeError(
            "args must be a dict, list, tuple, or set of numeric values"
        )

    return True

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")

    control_args = {}
    nested_args = {}

    i = 0
    while i < len(args):
        arg = args[i]
        if not isinstance(arg, str):
            raise TypeError(f"Argument at position {i} is not a string: {arg!r}")

        # Handle long options starting with '--'
        if arg.startswith("--"):
            key_val = arg[2:]
            if "=" in key_val:
                key, value = key_val.split("=", 1)
            else:
                key = key_val
                # Value may be the next argument if it doesn't start with '--'
                if i + 1 < len(args) and not args[i + 1].startswith("--"):
                    value = args[i + 1]
                    i += 1  # consume the value
                else:
                    # No explicit value provided; treat as boolean flag
                    value = True
        else:
            # Positional or short option; skip or treat as error
            raise ValueError(f"Unexpected argument format: {arg!r}")

        # Determine category
        if key.startswith("control-"):
            control_key = key[len("control-") :]
            control_args[control_key] = value
        elif key.startswith("custom-"):
            custom_key = key[len("custom-") :]
            nested_args[custom_key] = value
        else:
            nested_args[key] = value

        i += 1

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: Updated dictionary
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if not extra_vars:
            return vars_dict

        # Accept a single string as a list of key=value pairs separated by spaces
        if isinstance(extra_vars, str):
            # Split on whitespace but keep quoted strings together
            import shlex
            try:
                extra_vars = shlex.split(extra_vars)
            except ValueError:
                # If shlex fails, treat the whole string as one item
                extra_vars = [extra_vars]

        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list, tuple, or string")

        for item in extra_vars:
            if not isinstance(item, str):
                # Skip non-string items
                continue
            if '=' not in item:
                # Skip items that don't contain a key=value pair
                continue
            key, value = item.split('=', 1)
            key = key.strip()
            if not key:
                continue
            value = value.strip()
            # Try to interpret the value as JSON (e.g., numbers, booleans, lists, dicts)
            try:
                import json
                parsed_value = json.loads(value)
            except (json.JSONDecodeError, TypeError):
                parsed_value = value
            vars_dict[key] = parsed_value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess

    # Basic validation
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build the base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("verbose level must be non-negative")
            cmd.extend(["-" + "v" * verbose])
        elif isinstance(verbose, str):
            # Accept strings like 'v', 'vv', etc.
            if not all(c == "v" for c in verbose):
                raise ValueError("verbose string must consist of 'v' characters")
            cmd.append("-" + verbose)
        else:
            raise TypeError("verbose must be int or str")

    # Extra vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        # Convert to JSON string
        try:
            extra_json = json.dumps(extra_vars)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"extra_vars could not be JSON-encoded: {exc}") from exc
        cmd.extend(["--extra-vars", extra_json])

    # Additional ansible arguments
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError(f"ansible_args key must be a string, got {type(key)}")
            # Ensure key starts with '--' or '-'
            if not key.startswith("-"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
                # If False, skip adding the flag
            elif value is None:
                # Treat None as a flag without value
                cmd.append(key)
            else:
                cmd.extend([key, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # If the command failed, raise an error with output
    if result.returncode != 0:
        err_msg = (
            f"ansible-playbook failed with return code {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"Stdout:\n{result.stdout}\n"
            f"Stderr:\n{result.stderr}"
        )
        raise RuntimeError(err_msg)

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings. This method attempts to convert
    string values to bool, int, float, None, or list (comma separated) where
    appropriate. If a conversion fails, the original string is retained.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc.
    :param values_dict: The dict of arguments to be cast.
    """
    def _cast_value(val):
        # Strip whitespace
        if isinstance(val, str):
            val = val.strip()
        # Empty string stays as empty string
        if val == '':
            return ''
        # None-like values
        if isinstance(val, str) and val.lower() in ('none', 'null'):
            return None
        # Boolean values
        if isinstance(val, str) and val.lower() in ('true', 'false'):
            return val.lower() == 'true'
        # List values (comma separated)
        if isinstance(val, str) and ',' in val:
            items = [item.strip() for item in val.split(',')]
            # Recursively cast each item
            return [_cast_value(item) for item in items]
        # Integer
        try:
            if isinstance(val, str) and val.isdigit():
                return int(val)
            if isinstance(val, str):
                return int(val)
        except ValueError:
            pass
        # Float
        try:
            if isinstance(val, str):
                return float(val)
        except ValueError:
            pass
        # Return original value if no conversion succeeded
        return val

    # Iterate over a copy of items to avoid runtime errors when modifying dict
    for key, value in list(values_dict.items()):
        if isinstance(value, str):
            values_dict[key] = _cast_value(value)
        else:
            # If the value is already a non-string type, leave it unchanged
            continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    if not os.path.isdir(plugin_dir):
        raise NotADirectoryError(f"Provided path is not a directory: {plugin_dir}")

    plugin_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(plugin_path):
        raise FileNotFoundError(f"plugin.json not found in {plugin_dir}")

    try:
        with open(plugin_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in {plugin_path}: {exc}") from exc

    def _flatten(d, parent_key="", sep="."):
        flat = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, new_key, sep=sep))
            else:
                flat[new_key] = value
        return flat

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    # If the variable is not set or is an empty string, set a default path
    if not os.environ.get(env_var):
        try:
            # Default to a config.yaml file in the current working directory
            default_path = os.path.join(os.getcwd(), 'config.yaml')
        except Exception as exc:
            raise RuntimeError(f"Unable to determine default config path: {exc}") from exc
        os.environ[env_var] = default_path
    return None
